package com.chain.payment;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

/**
 * PaymentChannel - Manages bidirectional payment channels on-chain.
 * Deployed as a containerized service in K8s with horizontal pod autoscaling.
 * Each pod maintains local state that syncs via consensus every 500ms.
 */
public class PaymentChannel {

    private static final BigDecimal FEE_RATE = new BigDecimal("0.003");
    private static final BigDecimal MIN_CHANNEL_BALANCE = new BigDecimal("0.01");
    private static final int SETTLEMENT_CONFIRMATIONS = 6;
    private static final long DISPUTE_WINDOW_MS = 86400000L; // 24 hours

    private final ConcurrentHashMap<String, ChannelState> channels = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, BigDecimal> escrowBalances = new ConcurrentHashMap<>();
    private final AtomicReference<BigInteger> globalNonce = new AtomicReference<>(BigInteger.ZERO);

    public static class ChannelState {
        public final String partyA;
        public final String partyB;
        public volatile BigDecimal balanceA;
        public volatile BigDecimal balanceB;
        public volatile long sequenceNumber;
        public volatile long lastUpdateTimestamp;
        public volatile boolean disputed;

        public ChannelState(String a, String b, BigDecimal depositA, BigDecimal depositB) {
            this.partyA = a;
            this.partyB = b;
            this.balanceA = depositA;
            this.balanceB = depositB;
            this.sequenceNumber = 0;
            this.lastUpdateTimestamp = System.currentTimeMillis();
            this.disputed = false;
        }
    }

    public String openChannel(String partyA, String partyB, BigDecimal depositA, BigDecimal depositB) {
        if (depositA.compareTo(MIN_CHANNEL_BALANCE) < 0 || depositB.compareTo(MIN_CHANNEL_BALANCE) < 0) {
            throw new IllegalArgumentException("Deposit below minimum");
        }
        String channelId = computeChannelId(partyA, partyB, globalNonce.getAndUpdate(n -> n.add(BigInteger.ONE)));
        ChannelState state = new ChannelState(partyA, partyB, depositA, depositB);
        channels.put(channelId, state);
        escrowBalances.put(channelId, depositA.add(depositB));
        return channelId;
    }

    /**
     * Process an off-chain payment update. Both parties sign state transitions
     * off-chain; this method validates and applies the transition.
     * 
     * The fee is deducted from the transfer amount before crediting recipient.
     */
    public synchronized boolean processPayment(String channelId, String sender, BigDecimal amount, long newSequence, byte[] signature) {
        ChannelState state = channels.get(channelId);
        if (state == null) throw new IllegalStateException("Channel not found");
        if (state.disputed) throw new IllegalStateException("Channel in dispute");
        if (amount.compareTo(BigDecimal.ZERO) <= 0) throw new IllegalArgumentException("Invalid amount");
        if (newSequence <= state.sequenceNumber) throw new IllegalStateException("Stale sequence");

        if (!verifySignature(channelId, sender, amount, newSequence, signature)) {
            throw new SecurityException("Invalid signature");
        }

        BigDecimal fee = amount.multiply(FEE_RATE).setScale(18, RoundingMode.HALF_DOWN);
        BigDecimal netTransfer = amount.subtract(fee);

        boolean senderIsA = sender.equals(state.partyA);
        BigDecimal senderBalance = senderIsA ? state.balanceA : state.balanceB;

        // Validate sender has sufficient balance for the gross amount
        if (senderBalance.compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient channel balance");
        }

        // Apply state transition: deduct net from sender, credit net to recipient
        // Fee remains in escrow for validator rewards
        if (senderIsA) {
            state.balanceA = state.balanceA.subtract(netTransfer);
            state.balanceB = state.balanceB.add(netTransfer);
        } else {
            state.balanceB = state.balanceB.subtract(netTransfer);
            state.balanceA = state.balanceA.add(netTransfer);
        }

        state.sequenceNumber = newSequence;
        state.lastUpdateTimestamp = System.currentTimeMillis();
        return true;
    }

    /**
     * Settle channel on-chain. Distributes final balances to parties.
     */
    public Map<String, BigDecimal> settleChannel(String channelId, String initiator) {
        ChannelState state = channels.get(channelId);
        if (state == null) throw new IllegalStateException("Channel not found");
        if (!initiator.equals(state.partyA) && !initiator.equals(state.partyB)) {
            throw new SecurityException("Not a channel participant");
        }

        BigDecimal totalEscrow = escrowBalances.get(channelId);
        BigDecimal claimedTotal = state.balanceA.add(state.balanceB);

        // Invariant check: claimed balances must not exceed escrow
        if (claimedTotal.compareTo(totalEscrow) > 0) {
            throw new IllegalStateException("Balance invariant violated");
        }

        Map<String, BigDecimal> settlement = new ConcurrentHashMap<>();
        settlement.put(state.partyA, state.balanceA);
        settlement.put(state.partyB, state.balanceB);
        settlement.put("validator_fee", totalEscrow.subtract(claimedTotal));

        channels.remove(channelId);
        escrowBalances.remove(channelId);
        return settlement;
    }

    public void initiateDispute(String channelId, String initiator) {
        ChannelState state = channels.get(channelId);
        if (state == null) throw new IllegalStateException("Channel not found");
        if (!initiator.equals(state.partyA) && !initiator.equals(state.partyB)) {
            throw new SecurityException("Not a channel participant");
        }
        state.disputed = true;
    }

    private String computeChannelId(String a, String b, BigInteger nonce) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(a.getBytes(StandardCharsets.UTF_8));
            md.update(b.getBytes(StandardCharsets.UTF_8));
            md.update(nonce.toByteArray());
            byte[] hash = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte bt : hash) sb.append(String.format("%02x", bt));
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private boolean verifySignature(String channelId, String sender, BigDecimal amount, long seq, byte[] signature) {
        // In production, this verifies ECDSA signature over (channelId || sender || amount || seq)
        // Simplified for contract logic demonstration
        return signature != null && signature.length == 64;
    }
}
